mapper.select:
SELECT a.aid,a.uid,u.uname AS nickname,u.avatar,a.content,a.status,
       CONCAT(DATE_FORMAT(a.ct,'%Y-%m-%dT%H:%i:%s'),'+08:00') AS ct,
       a.handler,CONCAT(DATE_FORMAT(a.hct,'%Y-%m-%dT%H:%i:%s'),'+08:00') AS hct,a.reason

FROM appeal a LEFT JOIN user u ON u.uid=a.uid COLLATE utf8mb4_general_ci
a.status=#{status}
ORDER BY a.ct DESC,a.aid DESC LIMIT #{size} OFFSET #{offset}
